 private function saveItem(string$type,int$id,?int$item):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->cfg[$type]??null;if(!$c||!$c['items'])return$this->missing();$co=$this->company($u);$h=$this->row($c['table'],$id,$co);if(!$h)return$this->missing();if($this->code($c['status'],$c['statusCol'],(int)$h['status_id'])!=='DRAFT')return$this->conflict('Items can be changed only in DRAFT.');$in=$this->input()??[];$old=$item?$this->row($c['items'],$item,$co):null;if($item&&(!$old||(int)$old[$c['fk']]!==$id))return$this->missing();if($type==='work-orders'){$fs=['boq_item_id','budget_line_id','uom_id','item_code','description','ordered_quantity','rate','tax_percent','display_order','notes'];$req=['uom_id','item_code','description','ordered_quantity','rate'];}elseif($type==='measurements'){$fs=['work_order_item_id','description','location_reference','length_value','breadth_value','height_value','number_count','measured_quantity','accepted_quantity','rate','remarks'];$req=['work_order_item_id','measured_quantity','accepted_quantity','rate'];}else{$fs=['work_order_item_id','measurement_line_id','budget_line_id','description','current_quantity','rate','certified_amount','remarks'];$req=['work_order_item_id','description','current_quantity','rate'];}$d=array_intersect_key($in,array_flip($fs));$m=array_merge($old??[],$d);$e=$this->required($m,$req);$woi=$this->row('subcontract_work_order_items',(int)($m['work_order_item_id']??0),$co);if($type!=='work-orders'&&(!$woi||(int)$woi['work_order_id']!==(int)$h['work_order_id']))$e['work_order_item_id']='Select an item from this work order.';if($type==='work-orders'&&!empty($m['boq_item_id'])&&!db_connect()->table('boq_items')->where(['id'=>(int)$m['boq_item_id'],'company_id'=>$co,'project_id'=>(int)$h['project_id']])->where('deleted_at',null)->countAllResults())$e['boq_item_id']='Select a BOQ item from this project.';if($e)return$this->invalid($e);if($type==='work-orders')$d['amount']=round((float)$m['o