 private function recalc(string$type,int$id):void{$c=$this->cfg[$type];$db=db_connect();if($type==='work-orders'){$r=$db->table($c['items'])->select('SUM(amount) subtotal,SUM(amount*tax_percent/100) tax',false)->where($c['fk'],$id)->where('deleted_at',null)->get()->getRowArray();$sub=round((float)$r['subtotal'],2);$tax=round((float)$r['tax'],2);$wo=$db->table($c['table'])->where('id',$id)->get()->getRowArray();$db->table($c['table'])->where('id',$id)->update(['subtotal'=>$sub,'tax_amount'=>$tax,'total_order_value'=>$sub+$tax,'revised_order_value'=>$sub+$tax+(float)$wo['variation_amount']]);}elseif($type==='measurements'){$sum=(float)($db->table($c['items'])->selectSum('measured_amount')->where($c['fk'],$id)->where('deleted_at',null)->get()->getRowArray()['measured_amount']??0);$db->table($c['table'])->where('id',$id)->update(['total_measured_amount'=>$sum]);}else{$sum=(float)($db->table($c['items'])->selectSum('certified_amount')->where($c['fk'],$id)->where('deleted_at',null)->get()->getRowArray()['certified_amount']??0);$h=$db->table($c['table'])->where('id',$id)->get()->getRowArray();$taxable=$sum+(float)$h['variation_value']-(float)$h['material_recovery']-(float)$h['advance_recovery']-(float)$h['retention_amount']-(float)$h['other_recovery'];$gross=$taxable+(float)$h['cgst_amount']+(float)$h['sgst_amount']+(float)$h['igst_amount'];$net=$gross-(float)$h['tds_amount'];$db->table($c['table'])->where('id',$id)->update(['gross_work_value'=>$sum,'taxable_amount'=>$taxable,'gross_bill_amount'=>$gross,'net_certified_amount'=>$net,'outstanding_amount'=>$net-(float)$h['paid_amount']]);}}
 public function action(string$type,int$id,string$action):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->cfg[$type]??null;if(!$c)return$this->missing();$co=$this->company($u);$r=$this->row($c['table'],$id,$co);if(!$r||!$this->project((int)$r['project_id'],$u,true))return$this->missing();$old=$this->code($c['status'],$c['statusCol'],(int)$r['status_id']);$map=['work-orders'=>['submit'=>['DRAFT','SUBMITTED'],'approve'=>['SUBMITTED','APPROVED'],'reject'=>['SUBMITTED','REJECTED'],'activate'=>['APPROVED','ACTIVE'],'complete'=>['ACTIVE','COMPLETED'],'close'=>['COMPLETED','CLOSED'],'cancel'=>[['DRAFT','SUBMITTED','APPROVED'],'CANCELLED']],'measurements'=>['submit'=>['DRAFT','SUBMITTED'],'verify'=>['SUBMITTED','VERIFIED'],'approve'=>['VERIFIED','APPROVED'],'reject'=>[['SUBMITTED','VERIFIED'],'REJECTED'],'cancel'=>[['DRAFT','SUBMITTED'],'CANCELLED']],'ra-bills'=>['submit'=>['DRAFT','SUBMITTED'],'verify'=>['SUBMITTED','VERIFIED'],'approve'=>['VERIFIED','APPROVED'],'certify'=>['APPROVED','CERTIFIED'],'reject'=>[['SUBMITTED','VERIFIED','APPROVED'],'REJECTED'],'cancel'=>[['DRAFT','SUBMITTED'],'CANCELLED']],'payments'=>['submit'=>['DRAFT','SUBMITTED'],'approve'=>['SUBMITTED','APPROVED'],'mark-paid'=>['APPROVED','PAID'],'reject'=>['SUBMITTED','REJECTED'],'cancel'=>[['DRAFT','SUBMITTED','APPROVED'],'CANCELLED']]];$tr=$map[$type][$action]??null;if(!$tr)return$this->missing('Unsupported workflow action.');$from=(array)$tr[0];$new=$tr[1];if(!in_array($old,$from,true))return$this->conflict("Cannot {$action} {$c['key']} from {$old}.");if($c['items']&&in_array($action,['submit','verify','approve','certify'],true)&&db_connect()->table($c['items'])->where($c['fk'],$id)->where('deleted_at',null)->countAllResults()===0)return$this->invalid(['items'=>'At least one item is required.']);$sid=$this->masterId($c['status'],$c['statusCol'],$new);$in=$this->input()??[];$d=['status_id'=>$sid,'updated_by'=>(int)$u->id,'updated_at'=>$this->now()];
$stamp=['work-orders'=>['submit'=>['submitted_by','submitted_at'],'approve'=>['approved_by','approved_at']],'measurements'=>['verify'=>['verified_by','verified_at'],'approve'=>['approved_by','approved_at']],'ra-bills'=>['submit'=>['submitted_by','submitted_at'],'verify'=>['verified_by','verified_at'],'certify'=>['certified_by','certified_at']],'payments'=>['submit'=>['submitted_by','submitted_at'],'approve'=>['approved_by','approved_at'],'mark-paid'=>['paid_by','paid_at']]];if(isset($stamp[$type][$action])){$d[$stamp[$type][$action][0]]=(int)$u->id;$d[$stamp[$type][$action][1]]=$this->now();}
$db=db_connect();$db->transBegin();$db->table($c['table'])->where('id',$id)->update($d);if($type==='measurements'&&$new==='APPROVED'){foreach($db->table('subcontract_measurement_lines')->where('measurement_id',$id)->where('deleted_at',null)->get()->getResultArray()as$l)$db->table('subcontract_work_order_items')->where('id',$l['work_order_item_id'])->set('completed_quantity','completed_quantity+'.(float)$l['accepted_quantity'],false)->update();}if($type==='ra-bills'&&$new==='CERTIFIED'){foreach($db->table('subcontract_ra_bill_items')->where('ra_bill_id',$id)->where('deleted_at',null)->get()->getResultArray()as$l)$db->table('subcontract_work_order_items')->where('id',$l['work_order_item_id'])->set('certified_quantity','certified_quantity+'.(float)$l['current_quantity'],false)->update();$db->table('subcontract_work_orders')->where('id',$r['work_order_id'])->set('certified_amount','certified_amount+'.(float)$r['net_certified_amount'],false)->update();}if($type==='payments'&&$new==='PAID'){$bill=$this->row('subcontract_ra_bills',(int)$r['ra_bill_id'],$co);$paid=(float)$bill['paid_amount']+(float)$r['amount'];$out=max(0,(float)$bill['net_certified_amount']-$paid);$ps=$this->masterId('subcontract_ra_bills_payment_status_masters','payment_status_code',$out<=0?'PAID':'PARTIALLY_PAID');$db->table('subcontract_ra_bills')->where('id',$bill['id'])->update(['paid_amount'=>$paid,'outstanding_amount'=>$out,'payment_status_id'=>$ps]);$db->table('subcontract_work_orders')->where('id',$bill['work_order_id'])->set('paid_amount','paid_amount+'.(float)$r['amount'],false)->update();}$this->logStatus($c['entity'],$id,$old,$new,strtoupper(str_replace('-','_',$action)),$co,(int)$u->id,$in['remarks']??null);$db->transCommit();$fresh=$this->row($c['table'],$id,$co);$this->notifier->notify($type,$fresh,strtoupper(str_replace('-','_',$action)),(int)$u->id);return$this->show($type,$id);}
 public function integrations(int$workOrder):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$co=$this->company($u);$wo=$this->row('subcontract_work_orders',$workOrder,$co);if(!$wo||!$this->project((int)$wo['project_id'],$u))return$this->missing();$db=db_connect();$boq=array_column($db->table('subcontract_work_order_items')->select('boq_item_id')->where('work_order_id',$workOrder)->where('deleted_at',null)->where('boq_item_id !=',null)->get()->getResultArray(),'boq_item_id');$attendance=$db->table('labour_attendance_entries ae')->select('ae.*,ab.attendance_date,ab.project_id,ab.site_id,lw.worker_code,lw.worker_name,lc.contractor_code AS labour_contractor_code,lc.contractor_name AS labour_contractor_name')->join('labour_attendance_batches ab','ab.id=ae.batch_id')->join('labour_workers lw','lw.id=ae.worker_id AND lw.company_id=ae.company_id')->join('labour_contractors lc','lc.id=lw.contractor_id AND lc.company_id=lw.company_id')->where(['ae.company_id'=>$co,'ab.project_id'=>$wo['project_id'],'lc.subcontractor_id'=>$wo['contractor_id']]);if(!empty($wo['site_id']))$attendance->where('ab.site_id',$wo['site_id']);$out=['daily_work_progress'=>$boq?$db->table('daily_work_progress')->where('company_id',$co)->whereIn('boq_item_id',$boq)->where('deleted_at',null)->get()->getResultArray():[],'daily_manpower'=>$db->table('daily_site_manpower m')->select('m.*')->join('daily_site_reports r','r.id=m.daily_report_id')->where(['m.company_id'=>$co,'r.project_id'=>$wo['project_id'],'r.site_id'=>$wo['site_id']])->where('m.deleted_at',null)->get()->getResultArray(),'labour_attendance'=>$attendance->orderBy('ab.attendance_date','DESC')->get()->getResultArray(),'note'=>'Labour attendance is resolved once through labour_workers.contractor_id -> labour_contractors.subcontractor_id. It is operational evidence only and does not create a second bill or cost.'];return$this->ok('Supported Module 5 and Module 7 integrations retrieved successfully.','integrations',$out);}
